import pytest
import time
import json
from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.common.action_chains import ActionChains
from selenium.webdriver.support import expected_conditions
from selenium.webdriver.support.wait import WebDriverWait
from selenium.webdriver.common.keys import Keys
from selenium.webdriver.common.desired_capabilities import DesiredCapabilities

class TestSearch():
  def setup_method(self, method):
    self.driver = webdriver.Chrome()
    self.vars = {}
  
  def teardown_method(self, method):
    self.driver.quit()
  
  def test_search(self):
    self.driver.get("http://localhost:5173/login")
    self.driver.maximize_window()

    # 1. Login as Administrator
    WebDriverWait(self.driver, 10).until(
        expected_conditions.presence_of_element_located((By.NAME, "email"))
    )
    email_input = self.driver.find_element(By.NAME, "email")
    email_input.clear()
    email_input.send_keys("melbin@gmail.com")

    password_input = self.driver.find_element(By.NAME, "password")
    password_input.clear()
    password_input.send_keys("123456")

    self.driver.find_element(By.XPATH, "//button[@type='submit']").click()

    # 2. Wait for redirect to dashboard
    WebDriverWait(self.driver, 10).until(
        expected_conditions.url_contains("/administrator")
    )

    # 3. Navigate to Teacher Management
    self.driver.get("http://localhost:5173/administrator/teachers")

    # 4. Wait for the Teacher Search Input
    search_input = WebDriverWait(self.driver, 10).until(
        expected_conditions.element_to_be_clickable(
            (By.CSS_SELECTOR, "input.pr-4")
        )
    )

    # 5. Type 'Merlin'
    search_input.click()
    search_input.send_keys(Keys.CONTROL, "a")
    search_input.send_keys(Keys.BACKSPACE)
    search_input.send_keys("Merlin")
    time.sleep(1)

    # 6. Verify URL and search action
    assert "/administrator/teachers" in self.driver.current_url
    print("\n✅ TEACHER SEARCH TEST PASSED! Faculty directory searched for 'Merlin' successfully.")

if __name__ == "__main__":
    pytest.main(["test_searchh.py", "-v", "-s"])
